farms['key'] = farms['farm_name'].str.strip().str.lower()
reg['key'] = reg['farm_name'].str.strip().str.lower()
meta = reg.merge(farms[['key','timezone','installed_capacity_kw']], on='key', how='left').set_index('farm_id')
start_utc = pd.Timestamp('2024-03-15 00:00:00', tz='UTC')
end_utc = pd.Timestamp('2024-03-16 00:00:00', tz='UTC')
