    path = base / f'production_{farm_id}.csv'
    raw = path.read_bytes()
    enc = 'utf-16' if raw.startswith((b'\xff\xfe', b'\xfe\xff')) else 'utf-8'
    text = raw.decode(enc)
    sep = ';' if ';' in text.splitlines()[3] else ','
    df = pd.read_csv(path, skiprows=3, sep=sep, encoding=enc, dtype=str)
    return df, sep

def parse_ts(s):
    if pd.isna(s):
        return pd.NaT
    s = str(s).strip()
    if not s:
        return pd.NaT
    for fmt in ('%Y-%m-%d %H:%M:%S', '%d.%m.%Y %H:%M:%S'):
        try:
            return pd.Timestamp(datetime.strptime(s, fmt))
        except Exception:
            pass
    return pd.NaT

def normalize_number_str(s):
    if s is None:
        return None
    s = str(s).strip()
    if not s or s in {'ERR', 'N/A', 'offline', 'timeout', 'null'}:
        return None
    if '.' in s and ',' in s:
        return s.replace('.', '').replace(',', '.')
    if ',' in s:
        return s.replace(',', '.')
    return s

def parse_num(series):
    return pd.to_numeric(series.map(normalize_number_str), errors='coerce')

def prep(farm_id):
    df, sep = read_raw(farm_id)
    value_col = cal[farm_id]['calibration_data']['value_column_name']
    cols = [df.columns[0], 'inverter_temperature_C', value_col]
    datasets = {
        'full': df.drop_duplicates().copy(),
        'sub': df[cols].drop_duplicates().copy(),
    }
    out = {}
    for k, d in datasets.items():
        ts_col = d.columns[0]
        d['parsed_ts'] = d[ts_col].map(parse_ts)
        d['value_num'] = parse_num(d[value_col])
        d['temp_num'] = parse_num(d['inverter_temperature_C'])
        d = d[d['parsed_ts'].notna()].copy()
        tz = ZoneInfo(meta.loc[farm_id, 'timezone'])
        d['ts_local'] = pd.DatetimeIndex(d['parsed_ts']).tz_localize(tz)
        d['ts_utc'] = d['ts_local'].dt.tz_convert('UTC')
        out[k] = d
    return out

for method_dup in ['full','sub']:
    print('\nDUP', method_dup)
    for power_mode in ['nominal','forward_next','backward_prev']:
        print(' mode', power_mode)
        out = {}
        for farm_id in meta.index:
            datasets = prep(farm_id)
            d = datasets[method_dup].copy()
            for st_local, en_local in completed_maintenance.get(farm_id, []):
                tz = ZoneInfo(meta.loc[farm_id, 'timezone'])
                st_utc = st_local.tz_localize(tz).tz_convert('UTC')
                en_utc = en_local.tz_localize(tz).tz_convert('UTC')
