from __future__ import annotations

import json
import re
from datetime import datetime
from pathlib import Path
from typing import Any
from zoneinfo import ZoneInfo

import pandas as pd

DATASET_DIR = Path("/app/dataset")
ANSWER_JSON_PATH = Path("/app/answer.json")
REPORT_START_UTC = pd.Timestamp("2024-03-15 00:00:00", tz="UTC")
REPORT_END_UTC = pd.Timestamp("2024-03-16 00:00:00", tz="UTC")
INVALID_STRING_LITERALS = {"", "ERR", "N/A", "offline", "timeout", "null"}
# These numeric placeholders recur systematically across the dataset.
INVALID_NUMERIC_LITERALS = {"888888.8", "888888,8000", "-999.0", "-999,0000"}
ENERGY_UNIT_TO_KWH = {
    "btu": 0.00029307107,
    "kwh": 1.0,
    "mwh": 1000.0,
    "wh": 0.001,
}


def _normalize_name(value: str) -> str:
    return " ".join(str(value).strip().lower().split())


def _parse_timestamp(raw: Any) -> pd.Timestamp | pd.NaT:
    if pd.isna(raw):
        return pd.NaT
    text = str(raw).strip()
    if not text:
        return pd.NaT
    for fmt in ("%Y-%m-%d %H:%M:%S", "%d.%m.%Y %H:%M:%S"):
        try:
            return pd.Timestamp(datetime.strptime(text, fmt))
        except ValueError:
            continue
    return pd.NaT


def _normalize_number_string(raw: Any) -> str | None:
    if pd.isna(raw):
        return None
    text = str(raw).strip()
    if text in INVALID_STRING_LITERALS or text in INVALID_NUMERIC_LITERALS:
        return None
    if "." in text and "," in text:
        return text.replace(".", "").replace(",", ".")
    if "," in text:
        return text.replace(",", ".")
    return text or None


def _parse_number(raw: Any) -> float | None:
    normalized = _normalize_number_string(raw)
    if normalized is None:
        return None
    try:
        return float(normalized)
    except ValueError:
        return None


def _load_active_farms() -> dict[str, dict[str, Any]]:
    farms_df = pd.read_csv(DATASET_DIR / "farms.csv")
    registry_df = pd.read_csv(DATASET_DIR / "farm_registry.csv")
    farms_df["name_key"] = farms_df["farm_name"].map(_normalize_name)
    registry_df["name_key"] = registry_df["farm_name"].map(_normalize_name)
    merged = registry_df.merge(
        farms_df[["name_key", "farm_name", "timezone"]],
        on="name_key",
        how="inner",
    )
    metadata: dict[str, dict[str, Any]] = {}
    for row in merged.itertuples(index=False):
        metadata[row.farm_id] = {
            "farm_name": row.farm_name.strip(),
            "timezone": row.timezone,
        }
    return dict(sorted(metadata.items()))


def _load_calibration() -> dict[str, dict[str, Any]]:
    with (DATASET_DIR / "sensors_calibration.json").open() as fh:
        payload = json.load(fh)
    return payload["enterprise_platform"]["deployment_environments"]["system_config"][
        "farms"
    ]


def _load_completed_maintenance(
    active_farms: dict[str, dict[str, Any]],
) -> dict[str, list[tuple[pd.Timestamp, pd.Timestamp]]]:
    name_to_farm_id = {
        _normalize_name(meta["farm_name"]): farm_id
        for farm_id, meta in active_farms.items()
    }
    text = (DATASET_DIR / "maintenance_notes.txt").read_text()
    windows: dict[str, list[tuple[pd.Timestamp, pd.Timestamp]]] = {}

    ordinal_pattern = re.compile(
        r"on (?P<farm>.+?) on the (?P<day>\d+)(?:st|nd|rd|th) of March "
        r"from (?P<start>\d{2}:\d{2}) to (?P<end>\d{2}:\d{2}) local time\. "
        r"Status: COMPLETED\."
    )
    direct_pattern = re.compile(
        r"at (?P<farm>.+?) on March (?P<day>\d+), starting at "
        r"(?P<start>\d{2}:\d{2}) and finishing at (?P<end>\d{2}:\d{2}) "
        r"local time\. Status: COMPLETED\."
    )

    for pattern in (ordinal_pattern, direct_pattern):
        for match in pattern.finditer(text):
            farm_name = _normalize_name(match.group("farm"))
            farm_id = name_to_farm_id[farm_name]
            day = int(match.group("day"))
            start = pd.Timestamp(f"2024-03-{day:02d} {match.group('start')}:00")
            end = pd.Timestamp(f"2024-03-{day:02d} {match.group('end')}:00")
            windows.setdefault(farm_id, []).append((start, end))

    return windows


def _read_production_file(path: Path) -> pd.DataFrame:
    header_probe = path.read_bytes()
    encoding = "utf-16" if header_probe.startswith((b"\xff\xfe", b"\xfe\xff")) else "utf-8"
    text = header_probe.decode(encoding)
    delimiter = ";" if ";" in text.splitlines()[3] else ","
    return pd.read_csv(path, skiprows=3, sep=delimiter, encoding=encoding, dtype=str)


def _dominant_cadence_minutes(local_timestamps: pd.Series) -> float:
    deltas = local_timestamps.sort_values().diff().dropna().dt.total_seconds().div(60.0)
    positive_deltas = deltas[deltas > 0]
    if positive_deltas.empty:
        return 0.0
    return float(positive_deltas.mode().iloc[0])


def _calculate_farm_total(
    farm_id: str,
    active_farms: dict[str, dict[str, Any]],
    calibration_map: dict[str, dict[str, Any]],
    maintenance_windows: dict[str, list[tuple[pd.Timestamp, pd.Timestamp]]],
) -> int:
    calibration = calibration_map[farm_id]["calibration_data"]
    sensor_info = calibration_map[farm_id]["sensor_info"]
    value_column = calibration["value_column_name"]
    calibration_offset = float(calibration["calibration_offset"])
    timezone = ZoneInfo(active_farms[farm_id]["timezone"])

    df = _read_production_file(DATASET_DIR / f"production_{farm_id}.csv").drop_duplicates()
    timestamp_column = df.columns[0]

    df["parsed_timestamp"] = df[timestamp_column].map(_parse_timestamp)
    df = df[df["parsed_timestamp"].notna()].copy()
    if df.empty:
        return 0

    df["local_timestamp"] = pd.DatetimeIndex(df["parsed_timestamp"]).tz_localize(timezone)
    df["utc_timestamp"] = df["local_timestamp"].dt.tz_convert("UTC")
    df["value"] = df[value_column].map(_parse_number)
    df["inverter_temperature"] = df["inverter_temperature_C"].map(_parse_number)

    exclusion_mask = pd.Series(False, index=df.index)
    for local_start, local_end in maintenance_windows.get(farm_id, []):
        utc_start = local_start.tz_localize(timezone).tz_convert("UTC")
        utc_end = local_end.tz_localize(timezone).tz_convert("UTC")
        exclusion_mask |= (df["utc_timestamp"] >= utc_start) & (df["utc_timestamp"] < utc_end)

    shutdown_spikes = df.loc[df["inverter_temperature"] > 85.0, "utc_timestamp"]
    for spike_timestamp in shutdown_spikes:
        exclusion_mask |= (df["utc_timestamp"] > spike_timestamp) & (
            df["utc_timestamp"] < spike_timestamp + pd.Timedelta(minutes=45)
        )

    df = df[~exclusion_mask].copy()
    df = df[
        (df["utc_timestamp"] >= REPORT_START_UTC)
        & (df["utc_timestamp"] < REPORT_END_UTC)
    ].copy()
    if df.empty:
        return 0

    df["true_value"] = df["value"] - calibration_offset
    df = df[df["true_value"].notna() & (df["true_value"] >= 0)].copy()
    if df.empty:
        return 0

    if sensor_info["reading_type"] == "energy":
        unit = sensor_info["unit"].strip().lower()
        total_kwh = float(df["true_value"].sum()) * ENERGY_UNIT_TO_KWH[unit]
        return round(total_kwh)

    cadence_minutes = _dominant_cadence_minutes(df["local_timestamp"])
    total_kwh = float(df["true_value"].sum()) * (cadence_minutes / 60.0)
    return round(total_kwh)


def answer() -> dict[str, int]:
    active_farms = _load_active_farms()
    calibration_map = _load_calibration()
    maintenance_windows = _load_completed_maintenance(active_farms)
    return {
        farm_id: _calculate_farm_total(
            farm_id=farm_id,
            active_farms=active_farms,
            calibration_map=calibration_map,
            maintenance_windows=maintenance_windows,
        )
        for farm_id in active_farms
    }


if __name__ == "__main__":
    with ANSWER_JSON_PATH.open("w") as fh:
        json.dump(answer(), fh, default=list)

